def find_beautiful_sequence(k, q):
    from itertools import combinations

    def is_beautiful(seq):
        return len(set(s[0] for s in seq)) == len(seq)

    n = len(q)
    if k > n:
        print("NO")
        return

    for indices in combinations(range(1, n), k - 1):
        parts = [q[i:j] for i, j in zip((0,) + indices, indices + (n,))]
        if is_beautiful(parts):
            print("YES")
            for part in parts:
                print(part)
            return

    print("NO")

