def find_beautiful_sequence(k, q):
    from collections import defaultdict

    def backtrack(start, path):
        if len(path) == k:
            if ''.join(path) == q:
                return path
            return None

        for end in range(start + 1, len(q) + 1):
            substring = q[start:end]
            if substring[0] not in used_chars:
                used_chars.add(substring[0])
                path.append(substring)
                result = backtrack(end, path)
                if result:
                    return result
                path.pop()
                used_chars.remove(substring[0])

        return None

    used_chars = set()
    result = backtrack(0, [])

    if result:
        print("YES")
        for s in result:
            print(s)
    else:
        print("NO")

